// Post effect ChromaticEdges (@gameengine/materials, compiled; do not edit).
struct MaterialParams {
  p_strength: f32,
  p_inner: f32,
  p_outer: f32,
};
@group(1) @binding(0) var<uniform> material: MaterialParams;
fn material_post(in: PostInput) -> vec3f {
  let v0: vec2f = (in.screen_uv - 0.5);
  let v1: f32 = in.size.x;
  let v2: f32 = in.size.y;
  let v3: f32 = (v1 / v2);
  let v4: vec2f = vec2f(v3, 1.0);
  let v5: vec2f = (v0 * v4);
  let v6: f32 = length(v5);
  let v7: f32 = max(v6, 0.0001);
  let v8: vec2f = (v5 / v7);
  let v9: f32 = (v2 / 1080.0);
  let v10: f32 = (material.p_strength * v9);
  let v11: f32 = (v3 * 0.5);
  let v12: vec2f = vec2f(v11, 0.5);
  let v13: f32 = length(v12);
  let v14: f32 = (v6 / v13);
  let v15: f32 = smoothstep(material.p_inner, material.p_outer, v14);
  let v16: f32 = clamp(v15, 0.0, 1.0);
  let v17: f32 = (v10 * v16);
  let v18: vec2f = (v8 * v17);
  let v19: vec2f = (v18 * in.texel);
  let v20: vec2f = (in.screen_uv + v19);
  let v21: vec3f = post_color(v20);
  let v22: f32 = v21.x;
  let v23: vec3f = post_color(in.screen_uv);
  let v24: f32 = v23.y;
  let v25: vec2f = (in.screen_uv - v19);
  let v26: vec3f = post_color(v25);
  let v27: f32 = v26.z;
  let v28: vec3f = vec3f(v22, v24, v27);
  return v28;
}
